pub fn systemd_unit_directive_line(directive: Rc<SystemdUnitDirective>) -> String {
    match (*directive.clone()).clone() {
    SystemdUnitDirective::Description { text: v, .. } => Rc::new(vec!["Description=".to_string(), v.clone()]).join(&"".to_string()),
    SystemdUnitDirective::After { target: v, .. } => Rc::new(vec!["After=".to_string(), v.clone()]).join(&"".to_string()),
    SystemdUnitDirective::Before { target: v, .. } => Rc::new(vec!["Before=".to_string(), v.clone()]).join(&"".to_string()),
    SystemdUnitDirective::Wants { target: v, .. } => Rc::new(vec!["Wants=".to_string(), v.clone()]).join(&"".to_string()),
    SystemdUnitDirective::Requires { target: v, .. } => Rc::new(vec!["Requires=".to_string(), v.clone()]).join(&"".to_string()),
    SystemdUnitDirective::StartLimitIntervalSec { duration: v, .. } => Rc::new(vec!["StartLimitIntervalSec=".to_string(), v.clone()]).join(&"".to_string()),
    SystemdUnitDirective::StartLimitBurst { count: v, .. } => Rc::new(vec!["StartLimitBurst=".to_string(), v.clone()]).join(&"".to_string()),
    SystemdUnitDirective::OnSuccess { unit: v, .. } => Rc::new(vec!["OnSuccess=".to_string(), v.clone()]).join(&"".to_string()),
    SystemdUnitDirective::OnFailure { unit: v, .. } => Rc::new(vec!["OnFailure=".to_string(), v.clone()]).join(&"".to_string()),
    SystemdUnitDirective::Condition { kind: k, negated: n, argument: v, .. } => Rc::new(vec![systemd_condition_kind_wire(k.clone()), "=".to_string(), if n.clone() {
        "!".to_string()
    } else {
        "".to_string()
    }, v.clone()]).join(&"".to_string()),
    SystemdUnitDirective::Assert { kind: k, negated: n, argument: v, .. } => Rc::new(vec![systemd_assert_kind_wire(k.clone()), "=".to_string(), if n.clone() {
        "!".to_string()
    } else {
        "".to_string()
    }, v.clone()]).join(&"".to_string()),
    SystemdUnitDirective::SuccessAction { action: a, .. } => Rc::new(vec!["SuccessAction=".to_string(), systemd_unit_state_action_wire(a.clone())]).join(&"".to_string()),
    SystemdUnitDirective::FailureAction { action: a, .. } => Rc::new(vec!["FailureAction=".to_string(), systemd_unit_state_action_wire(a.clone())]).join(&"".to_string()),
}
}

